def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    blank_crosses = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and all(grid[rr][cc] == 3 for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                blank_crosses.add((r, c))
    empty_cols = {c for r, c in blank_crosses}

    for r, c, color in centers:
        own_spokes = {(r-1,c), (r+1,c), (r,c-1), (r,c+1)}
        for step in (-1, 1):
            j = c + step
            while 0 <= j < w:
                if original[r][j] == 3 and (r, j) not in own_spokes:
                    break
                if original[r][j] == 0 and j not in empty_cols:
                    out[r][j] = color
                j += step
        for step in (-1, 1):
            i = r + step
            while 0 <= i < h:
                if original[i][c] == 3 and (i, c) not in own_spokes:
                    break
                if original[i][c] == 0 and c not in empty_cols:
                    out[i][c] = color
                i += step

    # Vertical rays override horizontal rays at empty intersections.
    for r, c, color in centers:
        for step in (-1, 1):
            i = r + step
            while 0 <= i < h:
                if original[i][c] == 3 and (i, c) not in {(r-1,c), (r+1,c), (r,c-1), (r,c+1)}:
                    break
                if original[i][c] == 0 and c not in empty_cols:
                    out[i][c] = color
                i += step
    return out

